     4→using System;
     5→using System.Diagnostics;
     6→using System.Diagnostics.CodeAnalysis;
     7→using System.IO;
     8→using System.Linq;
     9→using System.Runtime.CompilerServices;
    10→using Nethermind.Core;
    11→using Nethermind.Core.Crypto;
    12→using Nethermind.Core.Specs;
    13→using Nethermind.Crypto;
    14→using Nethermind.Evm.CodeAnalysis;
    15→using Nethermind.Evm.EvmObjectFormat.Handlers;
    16→using Nethermind.Evm.Tracing;
    17→using Nethermind.Int256;
    18→using Nethermind.Logging;
    19→using Nethermind.Evm.State;
    20→using Nethermind.Evm.Tracing.State;
    21→using static Nethermind.Evm.EvmObjectFormat.EofValidator;
    22→
    23→namespace Nethermind.Evm.TransactionProcessing
    24→{
    25→    public sealed class TransactionProcessor(
    26→        ISpecProvider? specProvider,
    27→        IWorldState? worldState,
    28→        IVirtualMachine? virtualMachine,
    29→        ICodeInfoRepository? codeInfoRepository,
    30→        ILogManager? logManager)
    31→        : TransactionProcessorBase(specProvider, worldState, virtualMachine, codeInfoRepository, logManager);
    32→
    33→    public abstract class TransactionProcessorBase : ITransactionProcessor
    34→    {
    35→        protected EthereumEcdsa Ecdsa { get; }
    36→        protected ILogger Logger { get; }
    37→        protected ISpecProvider SpecProvider { get; }
    38→        protected IWorldState WorldState { get; }
    39→        protected IVirtualMachine VirtualMachine { get; }
    40→        private readonly ICodeInfoRepository _codeInfoRepository;
    41→        private SystemTransactionProcessor? _systemTransactionProcessor;
    42→        private readonly ILogManager _logManager;
    43→
    44→        [Flags]
    45→        protected enum ExecutionOptions
    46→        {
    47→            /// <summary>
    48→            /// Just accumulate the state
    49→            /// </summary>
    50→            None = 0,
    51→
    52→            /// <summary>
    53→            /// Commit the state after execution
    54→            /// </summary>
    55→            Commit = 1,
    56→
    57→            /// <summary>
    58→            /// Restore state after execution
    59→            /// </summary>
    60→            Restore = 2,
    61→
    62→            /// <summary>
    63→            /// Skip potential fail checks
    64→            /// </summary>
    65→            SkipValidation = 4,
    66→
    67→            /// <summary>
    68→            /// Skip potential fail checks and commit state after execution
    69→            /// </summary>
    70→            SkipValidationAndCommit = Commit | SkipValidation,
    71→
    72→            /// <summary>
    73→            /// Commit and later restore state also skip validation, use for CallAndRestore
    74→            /// </summary>
    75→            CommitAndRestore = Commit | Restore | SkipValidation
    76→        }
    77→
    78→        protected TransactionProcessorBase(
    79→            ISpecProvider? specProvider,
    80→            IWorldState? worldState,
    81→            IVirtualMachine? virtualMachine,
    82→            ICodeInfoRepository? codeInfoRepository,
    83→            ILogManager? logManager)
    84→        {
    85→            ArgumentNullException.ThrowIfNull(logManager, nameof(logManager));
    86→            ArgumentNullException.ThrowIfNull(specProvider, nameof(specProvider));
    87→            ArgumentNullException.ThrowIfNull(worldState, nameof(worldState));
    88→            ArgumentNullException.ThrowIfNull(virtualMachine, nameof(virtualMachine));
    89→            ArgumentNullException.ThrowIfNull(codeInfoRepository, nameof(codeInfoRepository));
    90→
    91→            Logger = logManager.GetClassLogger();
    92→            SpecProvider = specProvider;
    93→            WorldState = worldState;
    94→            VirtualMachine = virtualMachine;
    95→            _codeInfoRepository = codeInfoRepository;
    96→
    97→            Ecdsa = new EthereumEcdsa(specProvider.ChainId);
    98→            _logManager = logManager;
    99→        }
   100→
   101→        public void SetBlockExecutionContext(in BlockExecutionContext blockExecutionContext)
   102→            => VirtualMachine.SetBlockExecutionContext(in blockExecutionContext);
   103→
   104→        public void SetBlockExecutionContext(BlockHeader header)
   105→        {
   106→            IReleaseSpec spec = SpecProvider.GetSpec(header);
   107→            BlockExecutionContext blockExecutionContext = new(header, spec);
   108→            SetBlockExecutionContext(in blockExecutionContext);
   109→        }
   110→
   111→        public TransactionResult CallAndRestore(Transaction transaction, ITxTracer txTracer) =>
   112→            ExecuteCore(transaction, txTracer, ExecutionOptions.CommitAndRestore);
   113→
   114→        public TransactionResult BuildUp(Transaction transaction, ITxTracer txTracer)
   115→        {
   116→            // we need to treat the result of previous transaction as the original value of next transaction
   117→            // when we do not commit
   118→            WorldState.TakeSnapshot(true);
   119→            return ExecuteCore(transaction, txTracer, ExecutionOptions.None);
   120→        }
   121→
   122→        public TransactionResult Execute(Transaction transaction, ITxTracer txTracer) =>
   123→            ExecuteCore(transaction, txTracer, ExecutionOptions.Commit);
   124→
   125→        public TransactionResult Trace(Transaction transaction, ITxTracer txTracer) =>
   126→            ExecuteCore(transaction, txTracer, ExecutionOptions.SkipValidationAndCommit);
   127→
   128→        public virtual TransactionResult Warmup(Transaction transaction, ITxTracer txTracer) =>
   129→            ExecuteCore(transaction, txTracer, ExecutionOptions.SkipValidation);
   130→
   131→        private TransactionResult ExecuteCore(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
   132→        {
   133→            if (Logger.IsTrace) Logger.Trace($"Executing tx {tx.Hash}");
   134→            if (tx.IsSystem() || opts == ExecutionOptions.SkipValidation)
   135→            {
   136→                _systemTransactionProcessor ??= new SystemTransactionProcessor(SpecProvider, WorldState, VirtualMachine, _codeInfoRepository, _logManager);
   137→                return _systemTransactionProcessor.Execute(tx, tracer, opts);
   138→            }
   139→
   140→            TransactionResult result = Execute(tx, tracer, opts);
   141→            if (Logger.IsTrace) Logger.Trace($"Tx {tx.Hash} was executed, {result}");
   142→            return result;
   143→        }
   144→
   145→        protected virtual TransactionResult Execute(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
   146→        {
   147→            BlockHeader header = VirtualMachine.BlockExecutionContext.Header;
   148→            IReleaseSpec spec = GetSpec(header);
   149→
   150→            // restore is CallAndRestore - previous call, we will restore state after the execution
   151→            bool restore = opts.HasFlag(ExecutionOptions.Restore);
   152→            // commit - is for standard execute, we will commit thee state after execution
   153→            // !commit - is for build up during block production, we won't commit state after each transaction to support rollbacks
   154→            // we commit only after all block is constructed
   155→            bool commit = opts.HasFlag(ExecutionOptions.Commit) || (!opts.HasFlag(ExecutionOptions.SkipValidation) && !spec.IsEip658Enabled);
   156→
   157→            TransactionResult result;
   158→            IntrinsicGas intrinsicGas = CalculateIntrinsicGas(tx, spec);
   159→            if (!(result = ValidateStatic(tx, header, spec, opts, in intrinsicGas))) return result;
   160→
   161→            UInt256 effectiveGasPrice = CalculateEffectiveGasPrice(tx, spec.IsEip1559Enabled, header.BaseFeePerGas);
   162→
   163→            VirtualMachine.SetTxExecutionContext(new(tx.SenderAddress, _codeInfoRepository, tx.BlobVersionedHashes, in effectiveGasPrice));
   164→
   165→            UpdateMetrics(opts, effectiveGasPrice);
   166→
   167→            bool deleteCallerAccount = RecoverSenderIfNeeded(tx, spec, opts, effectiveGasPrice);
   168→
   169→            if (!(result = ValidateSender(tx, header, spec, tracer, opts))) return result;
   170→            if (!(result = BuyGas(tx, spec, tracer, opts, effectiveGasPrice, out UInt256 premiumPerGas, out UInt256 senderReservedGasPayment, out UInt256 blobBaseFee))) return result;
   171→            if (!(result = IncrementNonce(tx, header, spec, tracer, opts))) return result;
   172→
   173→            if (commit) WorldState.Commit(spec, tracer.IsTracingState ? tracer : NullTxTracer.Instance, commitRoots: false);
   174→
   175→            // substate.Logs contains a reference to accessTracker.Logs so we can't Dispose until end of the method
   176→            using StackAccessTracker accessTracker = new();
   177→
   178→            int delegationRefunds = (!spec.IsEip7702Enabled || !tx.HasAuthorizationList) ? 0 : ProcessDelegations(tx, spec, accessTracker);
   179→
   180→            long gasAvailable = tx.GasLimit - intrinsicGas.Standard;
   181→            if (!(result = BuildExecutionEnvironment(tx, spec, _codeInfoRepository, accessTracker, out ExecutionEnvironment env))) return result;
   182→
   183→            int statusCode = !tracer.IsTracingInstructions ?
   184→                ExecuteEvmCall<OffFlag>(tx, header, spec, tracer, opts, delegationRefunds, intrinsicGas, accessTracker, gasAvailable, env, out TransactionSubstate substate, out GasConsumed spentGas) :
   185→                ExecuteEvmCall<OnFlag>(tx, header, spec, tracer, opts, delegationRefunds, intrinsicGas, accessTracker, gasAvailable, env, out substate, out spentGas);
   186→
   187→            PayFees(tx, header, spec, tracer, in substate, spentGas.SpentGas, premiumPerGas, blobBaseFee, statusCode);
   188→            tx.SpentGas = spentGas.SpentGas;
   189→
   190→            // Finalize
   191→            if (restore)
   192→            {
   193→                WorldState.Reset(resetBlockChanges: false);
   194→                if (deleteCallerAccount)
   195→                {
   196→                    WorldState.DeleteAccount(tx.SenderAddress!);
   197→                }
   198→                else
   199→                {
   200→                    if (!opts.HasFlag(ExecutionOptions.SkipValidation))
   201→                        WorldState.AddToBalance(tx.SenderAddress!, senderReservedGasPayment, spec);
   202→                    DecrementNonce(tx);
   203→
   204→                    WorldState.Commit(spec, commitRoots: false);
   205→                }
   206→            }
   207→            else if (commit)
   208→            {
   209→                WorldState.Commit(spec, tracer.IsTracingState ? tracer : NullStateTracer.Instance, commitRoots: !spec.IsEip658Enabled);
   210→            }
   211→            else
   212→            {
   213→                WorldState.ResetTransient();
   214→            }
   215→
   216→            if (tracer.IsTracingReceipt)
   217→            {
   218→                Hash256 stateRoot = null;
   219→                if (!spec.IsEip658Enabled)
   220→                {
   221→                    WorldState.RecalculateStateRoot();
   222→                    stateRoot = WorldState.StateRoot;
   223→                }
   224→
   225→                if (statusCode == StatusCode.Failure)
   226→                {
   227→                    byte[] output = substate.ShouldRevert ? substate.Output.Bytes.ToArray() : [];
   228→                    tracer.MarkAsFailed(env.ExecutingAccount, spentGas, output, substate.Error, stateRoot);
   229→                }
   230→                else
   231→                {
   232→                    LogEntry[] logs = substate.Logs.Count != 0 ? substate.Logs.ToArray() : [];
   233→                    tracer.MarkAsSuccess(env.ExecutingAccount, spentGas, substate.Output.Bytes.ToArray(), logs, stateRoot);
   234→                }
   235→            }
   236→
   237→            if (substate.EvmExceptionType != EvmExceptionType.None)
   238→                return TransactionResult.EvmException(substate.EvmExceptionType);
   239→
   240→            return TransactionResult.Ok;
   241→        }
   242→
   243→        [MethodImpl(MethodImplOptions.NoInlining)]
   244→        private int ProcessDelegations(Transaction tx, IReleaseSpec spec, in StackAccessTracker accessTracker)
   245→        {
   246→            Debug.Assert(spec.IsEip7702Enabled && tx.HasAuthorizationList);
   247→
   248→            int refunds = 0;
   249→            foreach (AuthorizationTuple authTuple in tx.AuthorizationList)
   250→            {
   251→                Address authority = (authTuple.Authority ??= Ecdsa.RecoverAddress(authTuple));
   252→
   253→                if (!IsValidForExecution(authTuple, accessTracker, out string? error))
   254→                {
   255→                    if (Logger.IsDebug) Logger.Debug($"Delegation {authTuple} is invalid with error: {error}");
   256→                }
   257→                else
   258→                {
   259→                    if (!WorldState.AccountExists(authority))
   260→                    {
   261→                        WorldState.CreateAccount(authority, 0, 1);
   262→                    }
   263→                    else
   264→                    {
   265→                        refunds++;
   266→                        WorldState.IncrementNonce(authority);
   267→                    }
   268→
   269→                    _codeInfoRepository.SetDelegation(authTuple.CodeAddress, authority, spec);
   270→                }
   271→            }
   272→
   273→            return refunds;
   274→
   275→            bool IsValidForExecution(
   276→                AuthorizationTuple authorizationTuple,
   277→                StackAccessTracker accessTracker,
   278→                [NotNullWhen(false)] out string? error)
   279→            {
   280→                if (authorizationTuple.ChainId != 0 && SpecProvider.ChainId != authorizationTuple.ChainId)
   281→                {
   282→                    error = $"Chain id ({authorizationTuple.ChainId}) does not match.";
   283→                    return false;
   284→                }
   285→
   286→                if (authorizationTuple.Nonce == ulong.MaxValue)
   287→                {
   288→                    error = $"Nonce ({authorizationTuple.Nonce}) must be less than 2**64 - 1.";
   289→                    return false;
   290→                }
   291→
   292→                UInt256 s = new(authorizationTuple.AuthoritySignature.SAsSpan, isBigEndian: true);
   293→                if (authorizationTuple.Authority is null
   294→                    || s > Secp256K1Curve.HalfN
   295→                    //V minus the offset can only be 1 or 0 since eip-155 does not apply to Setcode signatures
   296→                    || authorizationTuple.AuthoritySignature.V - Signature.VOffset > 1)
   297→                {
   298→                    error = "Bad signature.";
   299→                    return false;
   300→                }
   301→
   302→                accessTracker.WarmUp(authorizationTuple.Authority);
   303→
   304→                if (WorldState.HasCode(authorizationTuple.Authority) && !_codeInfoRepository.TryGetDelegation(authorizationTuple.Authority, spec, out _))
   305→                {
   306→                    error = $"Authority ({authorizationTuple.Authority}) has code deployed.";
   307→                    return false;
   308→                }
   309→
   310→                UInt256 authNonce = WorldState.GetNonce(authorizationTuple.Authority);
   311→                if (authNonce != authorizationTuple.Nonce)
   312→                {
   313→                    error = $"Skipping tuple in authorization_list because nonce is set to {authorizationTuple.Nonce}, but authority ({authorizationTuple.Authority}) has {authNonce}.";
   314→                    return false;
   315→                }
   316→
   317→                error = null;
   318→                return true;
   319→            }
   320→        }
   321→
   322→        protected virtual IReleaseSpec GetSpec(BlockHeader header) => VirtualMachine.BlockExecutionContext.Spec;
   323→
   324→        private static void UpdateMetrics(ExecutionOptions opts, UInt256 effectiveGasPrice)
   325→        {
   326→            if (opts is ExecutionOptions.Commit or ExecutionOptions.None && (effectiveGasPrice[2] | effectiveGasPrice[3]) == 0)
   327→            {
   328→                float gasPrice = (float)((double)effectiveGasPrice / 1_000_000_000.0);
   329→
   330→                Metrics.BlockMinGasPrice = Math.Min(gasPrice, Metrics.BlockMinGasPrice);
   331→                Metrics.BlockMaxGasPrice = Math.Max(gasPrice, Metrics.BlockMaxGasPrice);
   332→
   333→                Metrics.BlockAveGasPrice = (Metrics.BlockAveGasPrice * Metrics.BlockTransactions + gasPrice) / (Metrics.BlockTransactions + 1);
   334→                Metrics.BlockEstMedianGasPrice += Metrics.BlockAveGasPrice * 0.01f * float.Sign(gasPrice - Metrics.BlockEstMedianGasPrice);
   335→                Metrics.BlockTransactions++;
   336→            }
   337→        }
   338→
   339→        /// <summary>
   340→        /// Validates the transaction, in a static manner (i.e. without accesing state/storage).
   341→        /// It basically ensures the transaction is well formed (i.e. no null values where not allowed, no overflows, etc).
   342→        /// As a part of validating the transaction the premium per gas will be calculated, to save computation this
   343→        /// is returned in an out parameter.
   344→        /// </summary>
   345→        /// <param name="tx">The transaction to validate</param>
   346→        /// <param name="header">The block containing the transaction. Only BaseFee is being used from the block atm.</param>
   347→        /// <param name="spec">The release spec with which the transaction will be executed</param>
   348→        /// <param name="opts">Options (Flags) to use for execution</param>
   349→        /// <param name="intrinsicGas">Calculated intrinsic gas</param>
   350→        /// <param name="floorGas"></param>
   351→        /// <returns></returns>
   352→        protected virtual TransactionResult ValidateStatic(
   353→            Transaction tx,
   354→            BlockHeader header,
   355→            IReleaseSpec spec,
   356→            ExecutionOptions opts,
   357→            in IntrinsicGas intrinsicGas)
   358→        {
   359→
   360→            bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
   361→
   362→            if (tx.SenderAddress is null)
   363→            {
   364→                TraceLogInvalidTx(tx, "SENDER_NOT_SPECIFIED");
   365→                return TransactionResult.SenderNotSpecified;
   366→            }
   367→
   368→            if (validate && tx.Nonce >= ulong.MaxValue - 1)
   369→            {
   370→                // we are here if nonce is at least (ulong.MaxValue - 1). If tx is contract creation,
   371→                // it is max possible value. Otherwise, (ulong.MaxValue - 1) is allowed, but ulong.MaxValue not.
   372→                if (tx.IsContractCreation || tx.Nonce == ulong.MaxValue)
   373→                {
   374→                    TraceLogInvalidTx(tx, "NONCE_OVERFLOW");
   375→                    return TransactionResult.NonceOverflow;
   376→                }
   377→            }
   378→
   379→            if (tx.IsAboveInitCode(spec))
   380→            {
   381→                TraceLogInvalidTx(tx, $"CREATE_TRANSACTION_SIZE_EXCEEDS_MAX_INIT_CODE_SIZE {tx.DataLength} > {spec.MaxInitCodeSize}");
   382→                return TransactionResult.TransactionSizeOverMaxInitCodeSize;
   383→            }
   384→
   385→            return ValidateGas(tx, header, intrinsicGas.MinimalGas, validate);
