   456→        {
   457→            bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
   458→
   459→            if (validate && WorldState.IsInvalidContractSender(spec, tx.SenderAddress!))
   460→            {
   461→                TraceLogInvalidTx(tx, "SENDER_IS_CONTRACT");
