   608→        private int ExecuteEvmCall<TTracingInst>(
   609→            Transaction tx,
   610→            BlockHeader header,
   611→            IReleaseSpec spec,
   612→            ITxTracer tracer,
   613→            ExecutionOptions opts,
   614→            int delegationRefunds,
   615→            IntrinsicGas gas,
   616→            in StackAccessTracker accessedItems,
   617→            long gasAvailable,
   618→            in ExecutionEnvironment env,
   619→            out TransactionSubstate substate,
   620→            out GasConsumed gasConsumed)
   621→            where TTracingInst : struct, IFlag
   622→        {
   623→            substate = default;
   624→            gasConsumed = tx.GasLimit;
   625→            byte statusCode = StatusCode.Failure;
   626→
   627→            Snapshot snapshot = WorldState.TakeSnapshot();
   628→
   629→            PayValue(tx, spec, opts);
   630→
   631→            if (env.CodeInfo is not null)
   632→            {
   633→                if (tx.IsContractCreation)
   634→                {
   635→                    // if transaction is a contract creation then recipient address is the contract deployment address
   636→                    if (!PrepareAccountForContractDeployment(env.ExecutingAccount, _codeInfoRepository, spec))
   637→                    {
   638→                        goto FailContractCreate;
   639→                    }
   640→                }
   641→            }
   642→            else
   643→            {
   644→                // If EOF header parsing or full container validation fails, transaction is considered valid and failing.
   645→                // Gas for initcode execution is not consumed, only intrinsic creation transaction costs are charged.
   646→                gasConsumed = gas.MinimalGas;
   647→                // If noValidation we didn't charge for gas, so do not refund; otherwise return unspent gas
   648→                if (!opts.HasFlag(ExecutionOptions.SkipValidation))
   649→                    WorldState.AddToBalance(tx.SenderAddress!, (ulong)(tx.GasLimit - gas.MinimalGas) * VirtualMachine.TxExecutionContext.GasPrice, spec);
   650→                goto Complete;
   651→            }
   652→
   653→            ExecutionType executionType = tx.IsContractCreation ? ((spec.IsEofEnabled && tx.IsEofContractCreation) ? ExecutionType.TXCREATE : ExecutionType.CREATE) : ExecutionType.TRANSACTION;
   654→
   655→            using (EvmState state = EvmState.RentTopLevel(gasAvailable, executionType, in env, in accessedItems, in snapshot))
   656→            {
   657→                substate = VirtualMachine.ExecuteTransaction<TTracingInst>(state, WorldState, tracer);
   658→                Metrics.IncrementOpCodes(VirtualMachine.OpCodeCount);
   659→                gasAvailable = state.GasAvailable;
   660→            }
   661→
   662→            if (tracer.IsTracingAccess)
   663→            {
   664→                tracer.ReportAccess(accessedItems.AccessedAddresses, accessedItems.AccessedStorageCells);
   665→            }
   666→
   667→            if (substate.ShouldRevert || substate.IsError)
   668→            {
   669→                if (Logger.IsTrace) Logger.Trace("Restoring state from before transaction");
   670→                WorldState.Restore(snapshot);
   671→            }
   672→            else
   673→            {
   674→                if (tx.IsContractCreation)
   675→                {
   676→                    if (!spec.IsEofEnabled || tx.IsLegacyContractCreation)
   677→                    {
   678→                        if (!DeployLegacyContract(spec, env.ExecutingAccount, in substate, in accessedItems, ref gasAvailable))
   679→                        {
   680→                            goto FailContractCreate;
   681→                        }
   682→                    }
   683→                    else
   684→                    {
   685→                        if (!DeployEofContract(spec, env.ExecutingAccount, in substate, in accessedItems, ref gasAvailable))
   686→                        {
   687→                            goto FailContractCreate;
   688→                        }
   689→                    }
   690→                }
   691→
   692→                foreach (Address toBeDestroyed in substate.DestroyList)
   693→                {
   694→                    if (Logger.IsTrace)
   695→                        Logger.Trace($"Destroying account {toBeDestroyed}");
   696→
   697→                    WorldState.ClearStorage(toBeDestroyed);
   698→                    WorldState.DeleteAccount(toBeDestroyed);
   699→
   700→                    if (tracer.IsTracingRefunds)
   701→                        tracer.ReportRefund(RefundOf.Destroy(spec.IsEip3529Enabled));
   702→                }
   703→
   704→                statusCode = StatusCode.Success;
   705→            }
   706→
   707→            gasConsumed = Refund(tx, header, spec, opts, in substate, gasAvailable,
   708→                VirtualMachine.TxExecutionContext.GasPrice, delegationRefunds, gas.FloorGas);
   709→            goto Complete;
   710→        FailContractCreate:
   711→            if (Logger.IsTrace) Logger.Trace("Restoring state from before transaction");
   712→            WorldState.Restore(snapshot);
   713→
   714→        Complete:
   715→            if (!opts.HasFlag(ExecutionOptions.SkipValidation))
   716→                header.GasUsed += gasConsumed.SpentGas;
   717→
   718→            return statusCode;
   719→        }
   720→
   721→        protected virtual bool DeployLegacyContract(IReleaseSpec spec, Address codeOwner, in TransactionSubstate substate, in StackAccessTracker accessedItems, ref long unspentGas)
   722→        {
   723→            long codeDepositGasCost = CodeDepositHandler.CalculateCost(spec, substate.Output.Bytes.Length);
   724→            if (unspentGas < codeDepositGasCost && spec.ChargeForTopLevelCreate)
   725→            {
   726→                return false;
   727→            }
   728→
   729→            if (CodeDepositHandler.CodeIsInvalid(spec, substate.Output.Bytes, 0))
   730→            {
   731→                return false;
   732→            }
   733→
   734→            if (unspentGas >= codeDepositGasCost)
   735→            {
   736→                // Copy the bytes so it's not live memory that will be used in another tx
   737→                byte[] code = substate.Output.Bytes.ToArray();
   738→                _codeInfoRepository.InsertCode(code, codeOwner, spec);
   739→                if (code.Length > CodeSizeConstants.MaxCodeSizeEip170)
   740→                {
   741→                    accessedItems.WarmUpLargeContract(codeOwner);
   742→                }
   743→
   744→                unspentGas -= codeDepositGasCost;
   745→            }
   746→
   747→            return true;
   748→        }
   749→
   750→        private bool DeployEofContract(IReleaseSpec spec, Address codeOwner, in TransactionSubstate substate, in StackAccessTracker accessedItems, ref long unspentGas)
   751→        {
   752→            // 1 - load deploy EOF subContainer at deploy_container_index in the container from which RETURNCODE is executed
   753→            ReadOnlySpan<byte> auxExtraData = substate.Output.Bytes.Span;
   754→            EofCodeInfo deployCodeInfo = (EofCodeInfo)substate.Output.DeployCode;
   755→
   756→            long codeDepositGasCost = CodeDepositHandler.CalculateCost(spec, deployCodeInfo.Code.Length + auxExtraData.Length);
   757→            if (unspentGas < codeDepositGasCost && spec.ChargeForTopLevelCreate)
   758→            {
   759→                return false;
   760→            }
   761→            int codeLength = deployCodeInfo.Code.Length + auxExtraData.Length;
   762→            // 3 - if updated deploy container size exceeds MAX_CODE_SIZE instruction exceptionally aborts
   763→            if (codeLength > spec.MaxCodeSize)
   764→            {
   765→                return false;
   766→            }
   767→            // 2 - concatenate data section with (aux_data_offset, aux_data_offset + aux_data_size) memory segment and update data size in the header
   768→            byte[] bytecodeResult = new byte[codeLength];
   769→            // 2 - 1 - 1 - copy old container
   770→            deployCodeInfo.Code.Span.CopyTo(bytecodeResult);
   771→            // 2 - 1 - 2 - copy aux data to dataSection
   772→            auxExtraData.CopyTo(bytecodeResult.AsSpan(deployCodeInfo.Code.Length));
   773→
   774→            // 2 - 2 - update data section size in the header u16
   775→            int dataSubHeaderSectionStart =
   776→                VERSION_OFFSET // magic + version
   777→                + Eof1.MINIMUM_HEADER_SECTION_SIZE // type section : (1 byte of separator + 2 bytes for size)
   778→                + ONE_BYTE_LENGTH + TWO_BYTE_LENGTH + TWO_BYTE_LENGTH * deployCodeInfo.EofContainer.Header.CodeSections.Count // code section :  (1 byte of separator + (CodeSections count) * 2 bytes for size)
   779→                + (deployCodeInfo.EofContainer.Header.ContainerSections is null
   780→                    ? 0 // container section :  (0 bytes if no container section is available)
   781→                    : ONE_BYTE_LENGTH + TWO_BYTE_LENGTH + TWO_BYTE_LENGTH * deployCodeInfo.EofContainer.Header.ContainerSections.Value.Count) // container section :  (1 byte of separator + (ContainerSections count) * 2 bytes for size)
   782→                + ONE_BYTE_LENGTH; // data section separator
   783→
   784→            ushort dataSize = (ushort)(deployCodeInfo.DataSection.Length + auxExtraData.Length);
   785→            bytecodeResult[dataSubHeaderSectionStart + 1] = (byte)(dataSize >> 8);
   786→            bytecodeResult[dataSubHeaderSectionStart + 2] = (byte)(dataSize & 0xFF);
   787→
   788→            if (unspentGas >= codeDepositGasCost)
   789→            {
   790→                // 4 - set state[new_address].code to the updated deploy container
   791→                // push new_address onto the stack (already done before the ifs)
   792→                _codeInfoRepository.InsertCode(bytecodeResult, codeOwner, spec);
   793→                if (bytecodeResult.Length > CodeSizeConstants.MaxCodeSizeEip170)
   794→                {
   795→                    accessedItems.WarmUpLargeContract(codeOwner);
   796→                }
   797→                unspentGas -= codeDepositGasCost;
   798→            }
   799→
   800→            return true;
   801→        }
