   808→        protected virtual void PayFees(Transaction tx, BlockHeader header, IReleaseSpec spec, ITxTracer tracer, in TransactionSubstate substate, long spentGas, in UInt256 premiumPerGas, in UInt256 blobBaseFee, int statusCode)
   809→        {
   810→            UInt256 fees = premiumPerGas * (ulong)spentGas;
   811→
   812→            // n.b. destroyed accounts already set to zero balance
   813→            bool gasBeneficiaryNotDestroyed = !substate.DestroyList.Contains(header.GasBeneficiary);
   814→            if (statusCode == StatusCode.Failure || gasBeneficiaryNotDestroyed)
   815→            {
   816→                WorldState.AddToBalanceAndCreateIfNotExists(header.GasBeneficiary!, fees, spec);
   817→            }
   818→
   819→            UInt256 eip1559Fees = !tx.IsFree() ? header.BaseFeePerGas * (ulong)spentGas : UInt256.Zero;
   820→            UInt256 collectedFees = spec.IsEip1559Enabled ? eip1559Fees : UInt256.Zero;
   821→
   822→            if (tx.SupportsBlobs && spec.IsEip4844FeeCollectorEnabled)
   823→            {
   824→                collectedFees += blobBaseFee;
   825→            }
   826→
   827→            if (spec.FeeCollector is not null && !collectedFees.IsZero)
   828→            {
   829→                WorldState.AddToBalanceAndCreateIfNotExists(spec.FeeCollector, collectedFees, spec);
   830→            }
   831→
   832→            if (tracer.IsTracingFees)
   833→            {
   834→                tracer.ReportFees(fees, eip1559Fees + blobBaseFee);
   835→            }
   836→        }
