    19→public class CodeInfoRepository : ICodeInfoRepository
    20→{
    21→    private static readonly CodeLruCache _codeCache = new();
    22→    private readonly FrozenDictionary<AddressAsKey, PrecompileInfo> _localPrecompiles;
    23→    private readonly IWorldState _worldState;
    24→
    25→    public CodeInfoRepository(IWorldState worldState, IPrecompileProvider precompileProvider)
    26→    {
    27→        _localPrecompiles = precompileProvider.GetPrecompiles();
    28→        _worldState = worldState;
    29→    }
    30→
    31→    public bool IsPrecompile(Address address, IReleaseSpec spec) =>
    32→        spec.IsPrecompile(address) && _localPrecompiles.ContainsKey(address);
    33→
    34→    public ICodeInfo GetCachedCodeInfo(Address codeSource, bool followDelegation, IReleaseSpec vmSpec, out Address? delegationAddress)
    35→    {
    36→        delegationAddress = null;
    37→        if (IsPrecompile(codeSource, vmSpec))
    38→        {
    39→            return _localPrecompiles[codeSource];
    40→        }
    41→
    42→        ICodeInfo cachedCodeInfo = InternalGetCachedCode(_worldState, codeSource, vmSpec);
    43→
    44→        if (!cachedCodeInfo.IsEmpty && TryGetDelegatedAddress(cachedCodeInfo.CodeSpan, out delegationAddress))
    45→        {
    46→            if (followDelegation)
    47→                cachedCodeInfo = InternalGetCachedCode(_worldState, delegationAddress, vmSpec);
    48→        }
    49→
    50→        return cachedCodeInfo;
    51→    }
    52→
    53→    private ICodeInfo InternalGetCachedCode(Address codeSource, IReleaseSpec vmSpec)
    54→    {
    55→        ref readonly ValueHash256 codeHash = ref _worldState.GetCodeHash(codeSource);
    56→        return InternalGetCachedCode(_worldState, in codeHash, vmSpec);
    57→    }
    58→
    59→    private static ICodeInfo InternalGetCachedCode(IReadOnlyStateProvider worldState, Address codeSource, IReleaseSpec vmSpec)
    60→    {
    61→        ValueHash256 codeHash = worldState.GetCodeHash(codeSource);
    62→        return InternalGetCachedCode(worldState, in codeHash, vmSpec);
    63→    }
    64→
    65→    private static ICodeInfo InternalGetCachedCode(IReadOnlyStateProvider worldState, in ValueHash256 codeHash, IReleaseSpec vmSpec)
    66→    {
    67→        ICodeInfo? cachedCodeInfo = null;
    68→        if (codeHash == Keccak.OfAnEmptyString.ValueHash256)
    69→        {
    70→            cachedCodeInfo = CodeInfo.Empty;
    71→        }
    72→
    73→        cachedCodeInfo ??= _codeCache.Get(in codeHash);
    74→        if (cachedCodeInfo is null)
    75→        {
    76→            byte[]? code = worldState.GetCode(in codeHash);
    77→
    78→            if (code is null)
    79→            {
    80→                MissingCode(in codeHash);
    81→            }
    82→
    83→            cachedCodeInfo = CodeInfoFactory.CreateCodeInfo(code, vmSpec, ValidationStrategy.ExtractHeader);
    84→            _codeCache.Set(in codeHash, cachedCodeInfo);
    85→        }
    86→        else
    87→        {
    88→            Metrics.IncrementCodeDbCache();
    89→        }
    90→
    91→        return cachedCodeInfo;
    92→
    93→        [DoesNotReturn, StackTraceHidden]
    94→        static void MissingCode(in ValueHash256 codeHash)
    95→        {
    96→            throw new DataException($"Code {codeHash} missing in the state");
    97→        }
    98→    }
    99→
   100→    public void InsertCode(ReadOnlyMemory<byte> code, Address codeOwner, IReleaseSpec spec)
   101→    {
   102→        ValueHash256 codeHash = code.Length == 0 ? ValueKeccak.OfAnEmptyString : ValueKeccak.Compute(code.Span);
   103→        // If the code is already in the cache, we don't need to create and add it again (and reanalyze it)
   104→        if (_worldState.InsertCode(codeOwner, in codeHash, code, spec) &&
   105→            _codeCache.Get(in codeHash) is null)
   106→        {
   107→            ICodeInfo codeInfo = CodeInfoFactory.CreateCodeInfo(code, spec, ValidationStrategy.ExtractHeader);
   108→            _codeCache.Set(in codeHash, codeInfo);
   109→        }
   110→    }
   111→
   112→    public void SetDelegation(Address codeSource, Address authority, IReleaseSpec spec)
   113→    {
   114→        if (codeSource == Address.Zero)
   115→        {
   116→            _worldState.InsertCode(authority, Keccak.OfAnEmptyString, Array.Empty<byte>(), spec);
   117→            return;
   118→        }
   119→        byte[] authorizedBuffer = new byte[Eip7702Constants.DelegationHeader.Length + Address.Size];
   120→        Eip7702Constants.DelegationHeader.CopyTo(authorizedBuffer);
   121→        codeSource.Bytes.CopyTo(authorizedBuffer, Eip7702Constants.DelegationHeader.Length);
   122→        ValueHash256 codeHash = ValueKeccak.Compute(authorizedBuffer);
   123→        if (_worldState.InsertCode(authority, codeHash, authorizedBuffer.AsMemory(), spec)
   124→            // If the code is already in the cache, we don't need to create CodeInfo and add it again (and reanalyze it)
   125→            && _codeCache.Get(in codeHash) is null)
   126→        {
   127→            _codeCache.Set(codeHash, new CodeInfo(authorizedBuffer));
   128→        }
   129→    }
   130→
   131→    /// <summary>
   132→    /// Retrieves code hash of delegation if delegated. Otherwise code hash of <paramref name="address"/>.
   133→    /// </summary>
   134→    /// <param name="worldState"></param>
   135→    /// <param name="address"></param>
   136→    public ValueHash256 GetExecutableCodeHash(Address address, IReleaseSpec spec)
   137→    {
   138→        ValueHash256 codeHash = _worldState.GetCodeHash(address);
   139→        if (codeHash == Keccak.OfAnEmptyString.ValueHash256)
   140→        {
   141→            return Keccak.OfAnEmptyString.ValueHash256;
   142→        }
   143→
   144→        ICodeInfo codeInfo = InternalGetCachedCode(_worldState, address, spec);
   145→        return codeInfo.IsEmpty
   146→            ? Keccak.OfAnEmptyString.ValueHash256
   147→            : codeHash;
   148→    }
   149→
   150→    /// <remarks>
   151→    /// Parses delegation code to extract the contained address.
   152→    /// <b>Assumes </b><paramref name="code"/> <b>is delegation code!</b>
   153→    /// </remarks>
   154→    private static bool TryGetDelegatedAddress(ReadOnlySpan<byte> code, [NotNullWhen(true)] out Address? address)
   155→    {
   156→        if (Eip7702Constants.IsDelegatedCode(code))
   157→        {
   158→            address = new Address(code[Eip7702Constants.DelegationHeader.Length..].ToArray());
   159→            return true;
   160→        }
   161→
   162→        address = null;
   163→        return false;
   164→    }
   165→
   166→    public bool TryGetDelegation(Address address, IReleaseSpec spec, [NotNullWhen(true)] out Address? delegatedAddress) =>
   167→        TryGetDelegatedAddress(InternalGetCachedCode(_worldState, address, spec).CodeSpan, out delegatedAddress);
   168→
   169→    public bool TryGetDelegation(in ValueHash256 codeHash, IReleaseSpec spec, [NotNullWhen(true)] out Address? delegatedAddress) =>
   170→        TryGetDelegatedAddress(InternalGetCachedCode(_worldState, in codeHash, spec).CodeSpan, out delegatedAddress);
   171→
   172→    private sealed class CodeLruCache
   173→    {
   174→        private const int CacheCount = 16;
   175→        private const int CacheMax = CacheCount - 1;
   176→        private readonly ClockCache<ValueHash256, ICodeInfo>[] _caches;
   177→
   178→        public CodeLruCache()
   179→        {
   180→            _caches = new ClockCache<ValueHash256, ICodeInfo>[CacheCount];
   181→            for (int i = 0; i < _caches.Length; i++)
   182→            {
   183→                // Cache per nibble to reduce contention as TxPool is very parallel
   184→                _caches[i] = new ClockCache<ValueHash256, ICodeInfo>(MemoryAllowance.CodeCacheSize / CacheCount);
   185→            }
   186→        }
   187→
   188→        public ICodeInfo? Get(in ValueHash256 codeHash)
   189→        {
   190→            ClockCache<ValueHash256, ICodeInfo> cache = _caches[GetCacheIndex(codeHash)];
   191→            return cache.Get(codeHash);
   192→        }
   193→
   194→        public bool Set(in ValueHash256 codeHash, ICodeInfo codeInfo)
   195→        {
   196→            ClockCache<ValueHash256, ICodeInfo> cache = _caches[GetCacheIndex(codeHash)];
   197→            return cache.Set(codeHash, codeInfo);
   198→        }
   199→
   200→        private static int GetCacheIndex(in ValueHash256 codeHash) => codeHash.Bytes[^1] & CacheMax;
   201→
   202→        public bool TryGet(in ValueHash256 codeHash, [NotNullWhen(true)] out ICodeInfo? codeInfo)
   203→        {
   204→            codeInfo = Get(in codeHash);
   205→            return codeInfo is not null;
   206→        }
   207→    }
   208→}
